const versions = `-- name: Versions :many
SELECT id, section_id, author, user_id, visibility_key, connections, markdown, diagram, cites, input_hash, lint, model, note, created_at FROM design_versions WHERE section_id = ANY($1::bigint[]) ORDER BY section_id, id DESC
`

// The versions of sections, newest first.
func (q *Queries) Versions(ctx context.Context, sections []int64) ([]DesignVersion, error) {
	rows, err := q.db.Query(ctx, versions, sections)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []DesignVersion
	for rows.Next() {
		var i DesignVersion
		if err := rows.Scan(
			&i.ID,
			&i.SectionID,
			&i.Author,
			&i.UserID,
			&i.VisibilityKey,
			&i.Connections,
			&i.Markdown,
			&i.Diagram,
			&i.Cites,
			&i.InputHash,
			&i.Lint,
			&i.Model,
			&i.Note,
			&i.CreatedAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}
